#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# Keep every stage inside run_wizard and the last line as is: bash then parses
# the whole file before the first prompt, so an edit mid-run can't break it.
# ──────────────────────────────────────────────────────────────────────────

run_wizard() {

TOTAL_STAGES=8

REPO_ROOT="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)"
cd "$REPO_ROOT"
CACHE_DIR="$HOME/.cache/geo-coach"
mkdir -p "$CACHE_DIR" && chmod 700 "$CACHE_DIR"
ENV_FILE="$CACHE_DIR/refresh.env"   # remembers the VPS host between runs; outside the repo
STAMP=$(date -u +%Y%m%dT%H%M%SZ)
DUMP="$CACHE_DIR/prod-$STAMP.dump"
IMAGES="$CACHE_DIR/prod-$STAMP-source-images.tar.gz"
DEV_DB_URL="postgres://geocoach:geocoach@localhost:5432/geocoach"
REMOTE_DIR="/srv/geo-coach"

banner "Refresh the dev database from production (#67)"

# ── 1 ─────────────────────────────────────────────────────────────────────
stage "Preflight"
say "Checking the tools this needs on your machine."
CLI=""
for c in docker podman; do command -v "$c" >/dev/null 2>&1 && { CLI="$c"; break; }; done
[[ -n "$CLI" ]] || { warn "Neither docker nor podman found."; exit 1; }
note "container tool: $CLI"
for t in ssh pnpm; do command -v "$t" >/dev/null 2>&1 || { warn "$t not found."; exit 1; }; done
note "ssh and pnpm found"
if command -v ss >/dev/null 2>&1 && ss -ltn 2>/dev/null | grep -q ':5173 '; then
  warn "Something is listening on :5173. That's probably pnpm dev."
  step "Stop pnpm dev (Ctrl-C in its terminal) so it doesn't hold the database open."
  pause "Press Enter once it's stopped"
fi

# ── 2 ─────────────────────────────────────────────────────────────────────
stage "VPS access"
say "Production runs on the VPS in $REMOTE_DIR. You'll reach it over SSH as 'deploy'."
note "The VPS address is the same value as the VPS_HOST GitHub secret (an IP or hostname)."
ask VPS_HOST "VPS address:"
write_env VPS_HOST "$VPS_HOST"
note "Leave the key file empty to use your normal SSH keys, or give a path such as ~/.ssh/geocoach_deploy."
ask SSH_KEY "SSH key file (optional):"
SSH_OPTS=(-o ConnectTimeout=10)
if [[ -n "$SSH_KEY" ]]; then
  SSH_KEY="${SSH_KEY/#\~/$HOME}"
  [[ -f "$SSH_KEY" ]] || { warn "No such file: $SSH_KEY"; exit 1; }
  SSH_OPTS+=(-i "$SSH_KEY" -o IdentitiesOnly=yes)
fi
write_env SSH_KEY "$SSH_KEY"
SSH_TARGET="deploy@$VPS_HOST"
say "Testing: ssh $SSH_TARGET, then checking production's Postgres is running…"
if ! ssh "${SSH_OPTS[@]}" "$SSH_TARGET" \
     "cd $REMOTE_DIR && docker compose ps --status running --services" > "$CACHE_DIR/services.txt"; then
  warn "SSH failed. Check the address and key file, and that the key is in /home/deploy/.ssh/authorized_keys."
  exit 1
fi
grep -q '^postgres$' "$CACHE_DIR/services.txt" || { warn "Production postgres isn't running. Aborting."; exit 1; }
printf '  %s✓%s reached production; running services: %s\n' "$GREEN" "$RESET" "$(tr '\n' ' ' < "$CACHE_DIR/services.txt")"
pause

# ── 3 ─────────────────────────────────────────────────────────────────────
stage "Dump production"
say "This only reads production: pg_dump takes a consistent snapshot while the site keeps running."
note "It's still kinder not to do this mid-Session."
say "Dumping the database to $DUMP …"
ssh "${SSH_OPTS[@]}" "$SSH_TARGET" "cd $REMOTE_DIR && docker compose exec -T postgres pg_dump -U geocoach -Fc geocoach" < /dev/null > "$DUMP"
chmod 600 "$DUMP"
[[ -s "$DUMP" ]] || { warn "The dump is empty. Aborting."; exit 1; }
printf '  %s✓%s database dump: %s\n' "$GREEN" "$RESET" "$(du -h "$DUMP" | cut -f1)"
say "Packing the Source images (they live outside the database)…"
if ssh "${SSH_OPTS[@]}" "$SSH_TARGET" "cd $REMOTE_DIR && docker compose exec -T web tar -C /data/source-images -czf - ." < /dev/null > "$IMAGES" && [[ -s "$IMAGES" ]]; then
  chmod 600 "$IMAGES"
  printf '  %s✓%s Source images: %s\n' "$GREEN" "$RESET" "$(du -h "$IMAGES" | cut -f1)"
else
  rm -f "$IMAGES"; IMAGES=""
  SKIPPED+=("Source images weren't copied, so Claim and Source images will be missing locally")
  warn "Couldn't copy Source images; continuing without them."
fi
pause

# ── 4 ─────────────────────────────────────────────────────────────────────
stage "Replace the dev database"
say "Starting dev Postgres from compose.dev.yml…"
"$CLI" compose -f compose.dev.yml up -d postgres >/dev/null 2>&1 || true
PG=""
for _ in $(seq 1 30); do
  PG=$("$CLI" ps --format '{{.Names}}' | grep -E '^geo-coach[_-]postgres[_-]1$' | head -n1 || true)
  [[ -n "$PG" ]] && "$CLI" exec "$PG" pg_isready -U geocoach -d postgres >/dev/null 2>&1 && break
  sleep 1
done
[[ -n "$PG" ]] || { warn "Dev Postgres didn't come up. Try: $CLI compose -f compose.dev.yml up postgres"; exit 1; }
note "dev Postgres container: $PG"
warn "This DELETES everything in your local dev database and replaces it with production's data."
note "Production is not touched."
if ! confirm "Replace the dev database now?"; then
  say "Stopped. Nothing local was changed; the dump is still in $CACHE_DIR."
  exit 0
fi
"$CLI" exec -i "$PG" psql -q -U geocoach -d postgres -v ON_ERROR_STOP=1 \
  -c "DROP DATABASE IF EXISTS geocoach WITH (FORCE);" -c "CREATE DATABASE geocoach OWNER geocoach;"
say "Restoring the dump (a minute or two for a big database)…"
if ! "$CLI" exec -i "$PG" pg_restore -U geocoach -d geocoach --no-owner --no-acl < "$DUMP" 2> "$CACHE_DIR/restore.log"; then
  warn "pg_restore reported problems; see $CACHE_DIR/restore.log"
  SKIPPED+=("Check $CACHE_DIR/restore.log for pg_restore errors")
fi
# Production login cookies and queued jobs mean nothing locally.
"$CLI" exec -i "$PG" psql -q -U geocoach -d geocoach -c "TRUNCATE auth_sessions, processing_jobs;" || true
printf '  %s✓%s dev database restored\n' "$GREEN" "$RESET"
pause

# ── 5 ─────────────────────────────────────────────────────────────────────
stage "Source images"
DEST="$REPO_ROOT/apps/web/data/source-images"
if [[ -n "$IMAGES" ]]; then
  say "Unpacking into apps/web/data/source-images (gitignored), where pnpm dev looks for them…"
  rm -rf "$DEST" && mkdir -p "$DEST"
  tar -C "$DEST" -xzf "$IMAGES"
  printf '  %s✓%s %s image files\n' "$GREEN" "$RESET" "$(find "$DEST" -type f | wc -l | tr -d ' ')"
else
  note "Skipped: no images were copied in stage 3."
fi
pause

# ── 6 ─────────────────────────────────────────────────────────────────────
stage "Migrate"
say "Your local main may be ahead of production, so apply any newer migrations"
say "and re-derive Games and Rounds, the same way a deploy does."
DATABASE_URL="$DEV_DB_URL" pnpm db:migrate
DATABASE_URL="$DEV_DB_URL" pnpm --filter @geo-coach/web db:rebuild-derived
printf '  %s✓%s schema up to date\n' "$GREEN" "$RESET"
pause

# ── 7 ─────────────────────────────────────────────────────────────────────
stage "Verify"
say "What's in the dev database now:"
"$CLI" exec -i "$PG" psql -U geocoach -d geocoach -c "
  SELECT (SELECT count(*) FROM duos) AS duos, (SELECT count(*) FROM games) AS games,
         (SELECT count(*) FROM rounds) AS rounds, (SELECT count(*) FROM sessions) AS sessions,
         (SELECT count(*) FROM utterances) AS utterances, (SELECT count(*) FROM learnings) AS learnings,
         (SELECT count(*) FROM claims) AS claims;"
say "Now check it in the app:"
step "Run: pnpm dev"
step "Open http://localhost:5173 and use the dev login as your own Player."
step "Open Sessions and click into one: you should see real Games, Rounds and transcripts."
pause "Press Enter when you've looked (pnpm dev can keep running)"

# ── 8 ─────────────────────────────────────────────────────────────────────
stage "Clean up"
say "The dump holds real transcripts. It sits outside the repo in $CACHE_DIR."
if confirm "Delete the dump files now? (keep them if you might restore again soon)"; then
  rm -f "$DUMP" "$IMAGES"
  printf '  %s✓%s deleted\n' "$GREEN" "$RESET"
else
  note "Kept: $DUMP"
  SKIPPED+=("Delete $CACHE_DIR/prod-*.dump when you no longer need it")
fi

finish
}

run_wizard "$@"; exit
